import fs from "node:fs";
import path from "node:path";
import { config } from "../config";
import { findSymlink, isGitPath, resolveInsideRoot } from "./safePath";

/**
 * Utility to write code generated by agents to the local filesystem.
 */
export const writeGeneratedCode = (
  actionsText: string,
  projectName: string,
) => {
  const safeProjectName =
    trimHyphens(
      projectName
        .normalize("NFKD")
        .replace(/[^a-zA-Z0-9_-]+/g, "-")
        .toLowerCase(),
    ) || "unknown-project";
  const outputDir = path.resolve(
    process.cwd(),
    "generated-code",
    safeProjectName,
  );
  return writeActionsToRoot(actionsText, outputDir);
};

const trimHyphens = (s: string) => {
  let start = 0;
  let end = s.length;
  while (start < end && s[start] === "-") start++;
  while (end > start && s[end - 1] === "-") end--;
  return s.slice(start, end);
};

interface GeneratedFile {
  filePath: string;
  code: string;
}

const FILE_HEADER = /^FILE:\s*(\S+)\s*$/;
const OPEN_FENCE = /^```[\w+-]*\s*$/;
const CLOSE_FENCE = /^```\s*$/;

/**
 * Parses FILE blocks line by line:
 *   FILE: path/to/file.ext
 *   ```lang
 *   code (may contain backticks and template literals)
 *   ```
 * A block ends at the first line that is exactly a closing fence.
 */
export const parseFileActions = (actionsText: string): GeneratedFile[] => {
  const lines = actionsText.split(/\r?\n/);
  const files: GeneratedFile[] = [];
  for (let i = 0; i < lines.length; i++) {
    const header = FILE_HEADER.exec(lines[i].trim());
    if (!header) continue;
    const filePath = header[1];
    if (!OPEN_FENCE.test(lines[i + 1]?.trim() ?? "")) {
      throw new Error(`FILE block is missing an opening fence: ${filePath}`);
    }
    const end = lines.findIndex(
      (line, index) => index > i + 1 && CLOSE_FENCE.test(line.trim()),
    );
    if (end === -1) {
      throw new Error(`FILE block is missing a closing fence: ${filePath}`);
    }
    const body = lines.slice(i + 2, end);
    files.push({
      filePath,
      code: body.length > 0 ? `${body.join("\n")}\n` : "",
    });
    i = end;
  }
  return files;
};

/**
 * Rejects symlinks anywhere between the root and the target so writes
 * cannot be redirected outside the root by links committed to a repo.
 */
const assertNoSymlinks = (root: string, relativePath: string) => {
  if (findSymlink(root, relativePath))
    throw new Error(`Generated file path traverses a symlink: ${relativePath}`);
};

export const writeActionsToRoot = (actionsText: string, outputDir: string) => {
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }
  const root = fs.realpathSync(outputDir);

  const files = parseFileActions(actionsText);
  if (files.length > config.generatedCodeMaxFiles) {
    throw new Error(
      `Generated output exceeds the ${config.generatedCodeMaxFiles}-file limit`,
    );
  }

  const writtenFiles: string[] = [];
  for (const { filePath, code } of files) {
    if (!filePath || path.isAbsolute(filePath) || filePath.includes("\0")) {
      throw new Error(`Unsafe generated file path: ${filePath}`);
    }
    if (Buffer.byteLength(code, "utf8") > config.generatedCodeMaxFileBytes) {
      throw new Error(`Generated file exceeds size limit: ${filePath}`);
    }

    const resolved = resolveInsideRoot(root, filePath);
    if (!resolved) {
      throw new Error(`Generated file escapes output directory: ${filePath}`);
    }
    const { fullPath, relativePath } = resolved;
    if (isGitPath(relativePath)) {
      throw new Error(`Generated file targets git metadata: ${filePath}`);
    }
    assertNoSymlinks(root, relativePath);

    fs.mkdirSync(path.dirname(fullPath), { recursive: true });
    fs.writeFileSync(fullPath, code);
    writtenFiles.push(relativePath);
  }

  return writtenFiles;
};
